package clusterdata.utils;

import org.apache.flink.streaming.api.functions.source.SourceFunction;
import java.io.*;
import java.util.zip.GZIPInputStream;

public class GzipCSVSource<T> implements SourceFunction<T> {
    private final String filePath;
    private final java.util.function.Function<String, T> parser;
    private volatile boolean isRunning = true;

    public GzipCSVSource(String filePath, java.util.function.Function<String, T> parser) {
        this.filePath = filePath;
        this.parser = parser;
    }

    @Override
    public void run(SourceContext<T> ctx) throws Exception {
        try (GZIPInputStream gzip = new GZIPInputStream(new FileInputStream(filePath));
             BufferedReader reader = new BufferedReader(new InputStreamReader(gzip))) {
            String line;
            while (isRunning && (line = reader.readLine()) != null) {
                T event = parser.apply(line);
                if (event != null) {
                    ctx.collect(event);
                }
            }
        }
    }

    @Override
    public void cancel() {
        isRunning = false;
    }
}
EOF
