import clusterdata.utils.GzipCSVSource;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.FilterFunction;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.windowing.WindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;
import java.io.FileWriter;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        System.out.println("output  " + outputPath);
        final long sesssize = params.getLong("sesssize", 600000); // 10 minutes in milliseconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // Read task events
        DataStream<TaskEvent> taskEvents = env.addSource(
            taskSourceOrTest(new GzipCSVSource<>(taskInput, TaskEvent::fromCSV))
        ).name("TaskEventSource");

        // Filter for SUBMIT events (eventType = 4) and assign timestamps (convert microseconds to milliseconds)
        DataStream<TaskEvent> submitEvents = taskEvents
            .filter(new FilterFunction<TaskEvent>() {
                @Override
                public boolean filter(TaskEvent event) throws Exception {
                    return event.eventType == 4; // SUBMIT event
                }
            })
            .assignTimestampsAndWatermarks(
                WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                    .withTimestampAssigner((event, recordTimestamp) -> event.timestamp / 1000) // Convert microseconds to milliseconds
            )
            .name("FilterSubmitEvents");

        // Group by jobId and apply session window (10 minutes = 600000 milliseconds)
        DataStream<Tuple2<Long, Long>> result = submitEvents
            .keyBy(new org.apache.flink.api.java.functions.KeySelector<TaskEvent, Long>() {
                @Override
                public Long getKey(TaskEvent event) throws Exception {
                    return event.jobId;
                }
            })
            .window(EventTimeSessionWindows.withGap(Time.milliseconds(sesssize)))
            .apply(new WindowFunction<TaskEvent, Tuple2<Long, Long>, Long, TimeWindow>() {
                @Override
                public void apply(Long jobId, TimeWindow window, Iterable<TaskEvent> events, Collector<Tuple2<Long, Long>> out) throws Exception {
                    long count = 0;
                    for (TaskEvent event : events) {
                        count++;
                    }
                    out.collect(new Tuple2<>(jobId, count));
                }
            })
            .name("SessionWindow");

        // Find max tasks per job
        DataStream<Tuple2<Long, Long>> maxPerJob = result
            .keyBy(new org.apache.flink.api.java.functions.KeySelector<Tuple2<Long, Long>, Long>() {
                @Override
                public Long getKey(Tuple2<Long, Long> value) throws Exception {
                    return value.f0;
                }
            })
            .reduce(new org.apache.flink.api.common.functions.ReduceFunction<Tuple2<Long, Long>>() {
                @Override
                public Tuple2<Long, Long> reduce(Tuple2<Long, Long> v1, Tuple2<Long, Long> v2) throws Exception {
                    return new Tuple2<>(v1.f0, Math.max(v1.f1, v2.f1));
                }
            })
            .name("FindMaxPerJob");

        // Write to file
        maxPerJob.addSink(new RichSinkFunction<Tuple2<Long, Long>>() {
            private transient FileWriter writer;

            @Override
            public void open(org.apache.flink.configuration.Configuration parameters) throws Exception {
                super.open(parameters);
                writer = new FileWriter(outputPath, false);
            }

            @Override
            public void invoke(Tuple2<Long, Long> value, Context context) throws Exception {
                synchronized(writer) {
                    writer.write("(" + value.f0 + "," + value.f1 + ")\n");
                    writer.flush();
                }
            }

            @Override
            public void close() throws Exception {
                if (writer != null) {
                    writer.close();
                }
                super.close();
            }
        }).name("FileSink");

        env.execute("LongestSessionPerJob");
    }
}
